const leads=$('Leads').all().map(i=>i.json).filter(x=>x.id);const clients=$('Clients').all().map(i=>i.json).filter(x=>x.id);const q=$('Rapport – Queue').all().map(i=>i.json).filter(x=>x.task_key);const logs=$input.all().map(i=>i.json);const now=paris();const isWeekly=new Date(day()+'T12:00:00Z').getUTCDay()===1&&Number(now.slice(11,13))===8;let start=day(),end=day();if(isWeekly){const d=new Date(day()+'T12:00:00Z');d.setUTCDate(d.getUTCDate()-7);start=d.toISOString().slice(0,10);d.setUTCDate(d.getUTCDate()+6);end=d.toISOString().slice(0,10);}const inRange=v=>v&&String(v).slice(0,10)>=start&&String(v).slice(0,10)<=end;const count=(a,f)=>a.filter(f).length;const pending=q.filter(t=>['needs_review','needs_attention','uncertain'].includes(t.status));const hot=pending.filter(t=>t.priority==='HOT');const errs=logs.filter(r=>r.resultat==='erreur'&&inRange(r.date));const title=isWeekly?'📊 تقرير أسبوعي أعمق':'📊 تقرير الإدارة';const text=`${title} — ${start}${isWeekly?' → '+end:''}\n📥 فرص مكتشفة: ${count(q,t=>t.type==='prospect'&&inRange(t.created_at))}\n📤 تواصل أول: ${count(leads,l=>inRange(l.date_envoi))} | متابعة: ${count(leads,l=>inRange(l.date_relance))}\n💬 ردود: ${count(leads,l=>inRange(l.date_reponse))} | مهتمون: ${count(leads,l=>l.statut==='interesse'&&inRange(l.date_reponse))}\n🌐 طلبات موقع: ${count(clients,l=>inRange(l.date))}\n🔥 HOT تحتاج قرارًا: ${hot.length} | إجمالي المراجعة: ${pending.length}\n🎬 بروفات محتوى: ${count(q,t=>t.type==='content'&&inRange(t.created_at))} | منشور مؤكد: ${count(q,t=>t.type==='content'&&t.status==='published'&&inRange(t.last_action))}\n🔎 مهام SEO: ${count(q,t=>['seo','seo_topic'].includes(t.type)&&inRange(t.created_at))}\n⚠️ أخطاء مسجلة: ${errs.length}\n📋 جاهز للفرق: ${count(q,t=>t.status==='ready')} | قيد العمل: ${count(q,t=>['running','reserved'].includes(t.status))}\n\nما يحتاجك:\n${pending.sort((a,b)=>(a.priority==='HOT'?-1:1)-(b.priority==='HOT'?-1:1)).slice(0,6).map(t=>'#'+t.id+' '+t.type+' — '+t.next_action).join('\n')||'لا شيء ع